use serde_json::{Value, json};
use std::{collections::{HashMap, HashSet}, fs, path::{Path, PathBuf}};
use duckdb::{Connection, Config};

const RATE: f64 = 50.0;
const TELEMETRY_SIZE: usize = 1888;
const SCORING_INFO_SIZE: usize = 548;
const PLAYER_SIZE: usize = 584;
const WHEEL_SIZE: usize = 260;
const GRAVITY: f64 = 9.80665;
const EARTH: f64 = 6_371_000.0;
const TIRE_RADIUS: f64 = 0.33;

#[derive(Clone)]
struct Meta { version:i32, recording:String, session:String, driver:String, car:String, class:String, track:String }
#[derive(Clone)]
struct Series { frequency:f64, columns:Vec<Vec<f64>> }
#[derive(Clone)]
struct Event { time:f64, values:Vec<Value> }
struct Loaded { meta:Meta, cont:HashMap<String,Series>, events:HashMap<String,Vec<Event>>, start:f64, duration:f64, track_len:f64, model:String }

const CONT: &[(&str,&[&str])] = &[
 ("Ground Speed", &["value"]),("GPS Latitude", &["value"]),("GPS Longitude", &["value"]),("G Force Lat", &["value"]),("G Force Vert", &["value"]),("G Force Long", &["value"]),("Engine RPM", &["value"]),("Throttle Pos Unfiltered", &["value"]),("Brake Pos Unfiltered", &["value"]),("Steering Pos Unfiltered", &["value"]),("Clutch Pos Unfiltered", &["value"]),("Fuel Level", &["value"]),("TC", &["value"]),("Regen Rate", &["value"]),("SoC", &["value"]),("Virtual Energy", &["value"]),("Lap Dist", &["value"]),("Ambient Temperature", &["value"]),("Track Temperature", &["value"]),
 ("Wheel Speed", &["value1","value2","value3","value4"]),("Susp Pos", &["value1","value2","value3","value4"]),("Brakes Temp", &["value1","value2","value3","value4"]),("TyresPressure", &["value1","value2","value3","value4"]),("TyresTempLeft", &["value1","value2","value3","value4"]),("TyresTempCentre", &["value1","value2","value3","value4"]),("TyresTempRight", &["value1","value2","value3","value4"]),("Tyres Wear", &["value1","value2","value3","value4"]),("TyresCarcassTemp", &["value1","value2","value3","value4"]),
];
const EVENTS: &[(&str,&[&str])] = &[("Lap", &["value"]),("Gear", &["value"]),("Engine Max RPM", &["value"]),("Current Sector", &["value"]),("RearFlapActivated", &["value"]),("Speed Limiter", &["value"]),("TCCut", &["value"]),("ABSLevel", &["value"]),("Best Sector 1", &["value"]),("Best Sector 2", &["value"]),("Last Sector 1", &["value"]),("Last Sector 2", &["value"]),("Current Sector 1", &["value"]),("Current Sector 2", &["value"]),("Best LapTime", &["value"]),("Lap Time", &["value"]),("In Pits", &["value"]),("Lap", &["value"] )];

fn quote(s:&str)->String { format!("\"{}\"",s.replace('"',"\"\"")) }
fn strval(v:&Value)->String { v.as_str().map(str::to_owned).unwrap_or_else(|| if v.is_null(){String::new()}else{v.to_string()}) }
fn number(v:&Value, fallback:f64)->f64 { v.as_f64().or_else(||v.as_i64().map(|x|x as f64)).or_else(||v.as_u64().map(|x|x as f64)).or_else(||v.as_bool().map(|x|if x{1.}else{0.})).or_else(||v.as_str().and_then(|x|x.parse().ok())).filter(|x|x.is_finite()).unwrap_or(fallback) }
fn put_c(buf:&mut [u8], at:usize, len:usize, s:&str) { if at>=buf.len() {return} let n=s.len().min(len.saturating_sub(1)).min(buf.len()-at); buf[at..at+n].copy_from_slice(&s.as_bytes()[..n]); }
fn i32le(b:&mut [u8], at:usize,v:i32){b[at..at+4].copy_from_slice(&v.to_le_bytes())}
fn i16le(b:&mut [u8],at:usize,v:i16){b[at..at+2].copy_from_slice(&v.to_le_bytes())}
fn f64le(b:&mut [u8],at:usize,v:f64){b[at..at+8].copy_from_slice(&v.to_le_bytes())}
fn f32le(b:&mut [u8],at:usize,v:f32){b[at..at+4].copy_from_slice(&v.to_le_bytes())}
fn cstring_epoch(s:&str)->i64 { let Some((date,time))=s.split_once('T') else{return 0}; let Some((year,rest))=date.split_once('-') else{return 0}; let Some((month,day))=rest.split_once('-') else{return 0}; let Some(t)=time.strip_suffix('Z') else{return 0}; let mut p=t.split('_'); let (Ok(y),Ok(m),Ok(d),Some(h),Some(mi),Some(sec))=(year.parse::<i64>(),month.parse::<i64>(),day.parse::<i64>(),p.next(),p.next(),p.next()) else{return 0}; let (Ok(h),Ok(mi),Ok(sec))=(h.parse::<i64>(),mi.parse::<i64>(),sec.parse::<i64>()) else{return 0}; let y=y-if m<=2{1}else{0}; let era=y.div_euclid(400); let yoe=y-era*400; let mp=m+if m>2{-3}else{9}; let doy=(153*mp+2)/5+d-1; let doe=yoe*365+yoe/4-yoe/100+doy; (((era*146097+doe-719468)*24+h)*60+mi)*60_000+sec*1000 }
fn session_ord(s:&str)->i32 {let x=s.trim().to_lowercase();if x.contains("race"){10}else if x.contains("qual"){5}else if x.contains("warm"){9}else{1}}
fn class_ord(s:&str)->u8 {let x=s.to_uppercase();if x.contains("HYPERCAR"){0}else if x.contains("LMP2"){3}else if x.contains("LMP3"){4}else if x.contains("GTE"){5}else if x.contains("GT3"){6}else{255}}
fn checksum(s:&str)->u32 {let mut c=0x811c9dc5u32;for b in s.bytes(){c^=b as u32;c=c.wrapping_mul(0x01000193)}c}
fn connection(path:&Path,read_only:bool)->Result<Connection,String>{let mode=if read_only{duckdb::AccessMode::ReadOnly}else{duckdb::AccessMode::ReadWrite};let config=Config::default().access_mode(mode).and_then(|c|c.enable_external_access(false)).and_then(|c|c.enable_autoload_extension(false)).and_then(|c|c.threads(1)).and_then(|c|c.max_memory("512MB")).map_err(|e|format!("Configure LMU DuckDB: {e}"))?;Connection::open_with_flags(path,config).map_err(|e|format!("Open LMU DuckDB: {e}"))}
fn rows(conn:&Connection,sql:&str)->Result<Vec<Vec<Value>>,String>{let mut stmt=conn.prepare(sql).map_err(|e|format!("Prepare DuckDB query: {e}"))?;let mut q=stmt.query([]).map_err(|e|format!("Run DuckDB query: {e}"))?;let n=q.as_ref().ok_or("DuckDB query returned no row set")?.column_count();let mut out=Vec::new();while let Some(r)=q.next().map_err(|e|format!("Read DuckDB rows: {e}"))?{let mut row=Vec::with_capacity(n);for i in 0..n{let v:duckdb::types::Value=r.get(i).map_err(|e|format!("Read DuckDB value: {e}"))?;row.push(match v{duckdb::types::Value::Null=>Value::Null,duckdb::types::Value::Boolean(x)=>json!(x),duckdb::types::Value::TinyInt(x)=>json!(x),duckdb::types::Value::SmallInt(x)=>json!(x),duckdb::types::Value::Int(x)=>json!(x),duckdb::types::Value::BigInt(x)=>json!(x),duckdb::types::Value::HugeInt(x)=>json!(x.to_string()),duckdb::types::Value::UTinyInt(x)=>json!(x),duckdb::types::Value::USmallInt(x)=>json!(x),duckdb::types::Value::UInt(x)=>json!(x),duckdb::types::Value::UBigInt(x)=>json!(x),duckdb::types::Value::Float(x)=>json!(x),duckdb::types::Value::Double(x)=>json!(x),duckdb::types::Value::Decimal(x)=>json!(x.to_string()),duckdb::types::Value::Text(x)=>json!(x),duckdb::types::Value::Blob(x)=>json!(x),duckdb::types::Value::Date32(x)=>json!(x.to_string()),duckdb::types::Value::Time64(_,x)=>json!(x.to_string()),duckdb::types::Value::Timestamp(_,x)=>json!(x.to_string()),_=>Value::Null})}out.push(row)}Ok(out)}
fn load(path:&Path)->Result<Loaded,String>{let conn=match connection(path,true){Ok(c)=>c,Err(read_error) if PathBuf::from(format!("{}.wal",path.display())).is_file()=>connection(path,false).map_err(|write_error|format!("{read_error}; private WAL recovery failed: {write_error}"))?,Err(e)=>return Err(e)};let meta_rows=rows(&conn,"SELECT key,value FROM metadata")?;let mut meta=HashMap::new();for r in meta_rows{if r.len()>=2{meta.insert(strval(&r[0]),strval(&r[1]));}}let track=meta.get("TrackName").map(|s|s.trim()).unwrap_or("");let car=meta.get("CarName").map(|s|s.trim()).unwrap_or("");if track.is_empty()||car.is_empty()||!meta.contains_key("RecordingTime"){return Err("DuckDB file is not an LMU telemetry recording".into())}let m=Meta{version:meta.get("Version").and_then(|x|x.parse().ok()).unwrap_or(1),recording:meta.get("RecordingTime").cloned().unwrap_or_default(),session:meta.get("SessionType").cloned().unwrap_or_else(||"Unknown".into()),driver:meta.get("DriverName").cloned().unwrap_or_else(||"Unknown".into()),car:car.into(),class:meta.get("CarClass").cloned().unwrap_or_else(||"Unknown".into()),track:track.into()};let tables=rows(&conn,"SELECT table_name FROM information_schema.tables WHERE table_schema='main'")?.into_iter().filter_map(|r|r.first().map(strval)).collect::<HashSet<_>>();if !tables.contains("channelsList")||!tables.contains("eventsList"){return Err("DuckDB file is missing LMU telemetry channel indexes".into())}let freqs=rows(&conn,"SELECT channelName,frequency FROM channelsList")?;let frequencies=freqs.into_iter().filter(|r|r.len()>1).map(|r|(strval(&r[0]),number(&r[1],0.))).collect::<HashMap<_,_>>();let mut cont=HashMap::new();for (name,cols) in CONT{let Some(freq)=frequencies.get(*name).copied().filter(|x|*x>0.) else{continue};if !tables.contains(*name){continue}let proj=cols.iter().map(|x|quote(x)).collect::<Vec<_>>().join(",");let rr=rows(&conn,&format!("SELECT {proj} FROM {}",quote(name)))?;let mut values=vec![Vec::with_capacity(rr.len());cols.len()];for row in rr{for (i,v) in row.iter().enumerate().take(values.len()){values[i].push(number(v,0.));}}cont.insert((*name).into(),Series{frequency:freq,columns:values});}let mut events=HashMap::new();for (name,cols) in EVENTS{if !tables.contains(*name){continue}let proj=std::iter::once("ts".to_string()).chain(cols.iter().map(|x|quote(x))).collect::<Vec<_>>().join(",");let mut entries=Vec::new();for r in rows(&conn,&format!("SELECT {proj} FROM {} ORDER BY {}",quote(name),quote("ts")))?{if !r.is_empty(){entries.push(Event{time:number(&r[0],0.),values:r[1..].to_vec()})}}events.insert((*name).into(),entries);}drop(conn);let start=events.values().flat_map(|x|x.iter().map(|e|e.time)).fold(f64::INFINITY,f64::min);let start=if start.is_finite(){start}else{0.};let duration=cont.values().map(|s|s.columns.first().map(|v|v.len().saturating_sub(1) as f64/s.frequency).unwrap_or(0.)).fold(0.,f64::max);let track_len=cont.get("Lap Dist").and_then(|s|s.columns.first()).into_iter().flatten().copied().fold(0.,f64::max);if duration<=0.||track_len<=0.{return Err("LMU telemetry recording contains no drivable samples".into())}let unnumbered=car.rsplit_once(" #").and_then(|(prefix,n)|if n.trim().parse::<u32>().is_ok(){Some(prefix.trim())}else{None}).unwrap_or(car);let model=String::from_utf8_lossy(&unnumbered.as_bytes()[..unnumbered.len().min(29)]).trim().to_string();Ok(Loaded{meta:m,cont,events,start,duration,track_len,model})}
fn cv(l:&Loaded,n:&str,t:f64,col:usize,fb:f64)->f64{l.cont.get(n).and_then(|s|s.columns.get(col).map(|v|(s,v))).and_then(|(s,v)|if v.is_empty(){None}else{let i=(((t-l.start)*s.frequency).floor() as isize).max(0) as usize;Some(v[i.min(v.len()-1)])}).unwrap_or(fb)}
fn ev(l:&Loaded,n:&str,t:f64,col:usize,fb:f64)->f64{let Some(es)=l.events.get(n)else{return fb};let i=es.partition_point(|e|e.time<=t);if i==0{return fb}number(es[i-1].values.get(col).unwrap_or(&Value::Null),fb)}
fn put_orientation(b:&mut[u8],x:f64,z:f64){let m=x.hypot(z);let(nx,nz)=if m>0.{(x/m,z/m)}else{(0.,1.)};f64le(b,232,nz);f64le(b,248,-nx);f64le(b,264,1.);f64le(b,280,-nx);f64le(b,296,-nz)}
fn synth(l:&Loaded,t:f64,epoch:i64)->Result<Vec<u8>,String>{let mut tel=vec![0;TELEMETRY_SIZE];let mut si=vec![0;SCORING_INFO_SIZE];let mut player=vec![0;PLAYER_SIZE];let lap=l.events.get("Lap").and_then(|x|{let i=x.partition_point(|e|e.time<=t);if i==0{None}else{Some(&x[i-1])}});let lapno=lap.map(|e|number(e.values.first().unwrap_or(&Value::Null),0.) as i32).unwrap_or(0);let lapstart=lap.map(|e|e.time).unwrap_or(l.start);let speed=cv(l,"Ground Speed",t,0,0.)/3.6;let lat=cv(l,"GPS Latitude",t,0,0.);let lon=cv(l,"GPS Longitude",t,0,0.);let olat=cv(l,"GPS Latitude",l.start,0,0.);let olon=cv(l,"GPS Longitude",l.start,0,0.);let nt=(l.start+l.duration).min(t+0.1);let nx=cv(l,"GPS Longitude",nt,0,0.);let nz=cv(l,"GPS Latitude",nt,0,0.);let rad=olat.to_radians();let x=(lon-olon).to_radians()*rad.cos()*EARTH;let z=(lat-olat).to_radians()*EARTH;let x2=(nx-olon).to_radians()*rad.cos()*EARTH;let z2=(nz-olat).to_radians()*EARTH;
i32le(&mut tel,0,1);f64le(&mut tel,4,1./RATE);f64le(&mut tel,12,t);i32le(&mut tel,20,lapno);f64le(&mut tel,24,lapstart);put_c(&mut tel,32,64,&l.meta.car);put_c(&mut tel,96,64,&l.meta.track);f64le(&mut tel,160,x);f64le(&mut tel,176,z);f64le(&mut tel,200,-speed);f64le(&mut tel,208,cv(l,"G Force Lat",t,0,0.)*GRAVITY);f64le(&mut tel,216,cv(l,"G Force Vert",t,0,0.)*GRAVITY);f64le(&mut tel,224,-cv(l,"G Force Long",t,0,0.)*GRAVITY);put_orientation(&mut tel,x2-x,z2-z);i32le(&mut tel,352,ev(l,"Gear",t,0,0.) as i32);f64le(&mut tel,356,cv(l,"Engine RPM",t,0,0.));f64le(&mut tel,388,cv(l,"Throttle Pos Unfiltered",t,0,0.)/100.);f64le(&mut tel,396,cv(l,"Brake Pos Unfiltered",t,0,0.)/100.);f64le(&mut tel,404,cv(l,"Steering Pos Unfiltered",t,0,0.)/100.);f64le(&mut tel,412,cv(l,"Clutch Pos Unfiltered",t,0,0.)/100.);f64le(&mut tel,524,cv(l,"Fuel Level",t,0,0.));f64le(&mut tel,532,ev(l,"Engine Max RPM",t,0,0.));i32le(&mut tel,600,ev(l,"Current Sector",t,0,0.) as i32);tel[617]=ev(l,"RearFlapActivated",t,0,0.) as u8;tel[748]=ev(l,"Speed Limiter",t,0,0.) as u8;tel[750]=cv(l,"TC",t,0,0.) as u8;tel[754]=ev(l,"TCCut",t,0,0.) as u8;tel[756]=ev(l,"ABSLevel",t,0,0.) as u8;f32le(&mut tel,768,cv(l,"Regen Rate",t,0,0.) as f32);f32le(&mut tel,772,cv(l,"SoC",t,0,0.) as f32);f32le(&mut tel,776,cv(l,"Virtual Energy",t,0,0.) as f32);put_c(&mut tel,796,30,&l.model);tel[826]=class_ord(&l.meta.class);
for i in 0..4{let w=848+i*WHEEL_SIZE;let ws=cv(l,"Wheel Speed",t,i,speed);f64le(&mut tel,w,cv(l,"Susp Pos",t,i,0.)/1000.);f64le(&mut tel,w+24,cv(l,"Brakes Temp",t,i,0.));f64le(&mut tel,w+40,ws/TIRE_RADIUS);f64le(&mut tel,w+56,ws-speed);f64le(&mut tel,w+72,speed);f64le(&mut tel,w+120,cv(l,"TyresPressure",t,i,0.));f64le(&mut tel,w+128,cv(l,"TyresTempLeft",t,i,0.)+273.15);f64le(&mut tel,w+136,cv(l,"TyresTempCentre",t,i,0.)+273.15);f64le(&mut tel,w+144,cv(l,"TyresTempRight",t,i,0.)+273.15);f64le(&mut tel,w+152,1.-cv(l,"Tyres Wear",t,i,100.)/100.);f64le(&mut tel,w+204,cv(l,"TyresCarcassTemp",t,i,0.)+273.15);}
put_c(&mut si,0,64,&l.meta.track);i32le(&mut si,64,session_ord(&l.meta.session));f64le(&mut si,68,t);f64le(&mut si,76,l.start+l.duration);f64le(&mut si,88,l.track_len);i32le(&mut si,104,1);si[108]=5;si[115]=1;put_c(&mut si,116,32,&l.meta.driver);f64le(&mut si,228,cv(l,"Ambient Temperature",t,0,0.));f64le(&mut si,236,cv(l,"Track Temperature",t,0,0.));i32le(&mut player,0,1);put_c(&mut player,4,32,&l.meta.driver);put_c(&mut player,36,64,&l.meta.car);f64le(&mut player,128,ev(l,"Best Sector 1",t,0,0.));f64le(&mut player,136,ev(l,"Best Sector 2",t,0,0.));f64le(&mut player,144,ev(l,"Best LapTime",t,0,0.));f64le(&mut player,152,ev(l,"Last Sector 1",t,0,0.));f64le(&mut player,160,ev(l,"Last Sector 2",t,0,0.));f64le(&mut player,168,ev(l,"Lap Time",t,0,0.));f64le(&mut player,176,ev(l,"Current Sector 1",t,0,0.));f64le(&mut player,184,ev(l,"Current Sector 2",t,0,0.));i16le(&mut player,100,lapno as i16);player[102]=ev(l,"Current Sector",t,0,0.) as u8;f64le(&mut player,104,cv(l,"Lap Dist",t,0,0.));player[196]=1;player[198]=ev(l,"In Pits",t,0,0.) as u8;put_c(&mut player,200,32,&l.meta.class);f64le(&mut player,256,lapstart);
let timestamp=epoch as f64+(t-l.start)*1000.;crate::games::lmu::encode_lmu_source_payload(l.meta.version,checksum(&l.meta.recording),timestamp,&tel,&si,Some(&player)) }
fn epoch_ms(s:&str)->i64 { cstring_epoch(s) }
fn copy_private(source:&Path,input:&Value,out:&Path,config:&Value)->Result<PathBuf,String>{let root=super::paths::staging_root(config)?;let source=source.canonicalize().map_err(|e|format!("Resolve DuckDB source: {e}"))?;if !source.starts_with(&root){return Err("DuckDB source is outside configured staging root".into())}let private=out.join("input.duckdb");fs::copy(&source,&private).map_err(|e|format!("Copy staged DuckDB privately: {e}"))?;let wal= input.pointer("/input/sidecarPath").and_then(Value::as_str).map(PathBuf::from);if let Some(wal)=wal{if !wal.is_absolute(){return Err("DuckDB WAL path must be absolute".into())}let wal=wal.canonicalize().map_err(|e|format!("Resolve staged DuckDB WAL: {e}"))?;if !wal.starts_with(&root)||!wal.is_file(){return Err("DuckDB WAL is outside configured staging root".into())}let expected=PathBuf::from(format!("{}.wal",source.display()));if wal!=expected.canonicalize().unwrap_or(expected){return Err("DuckDB WAL does not match staged database".into())}fs::copy(wal,format!("{}.wal",private.display())).map_err(|e|format!("Copy DuckDB WAL privately: {e}"))?;}Ok(private)}
fn preview(path:&Path)->Result<Value,String>{let l=load(path)?;let duration=l.duration;let lap_count=l.events.get("Lap").map(Vec::len).unwrap_or(0);if lap_count==0{return Err("LMU telemetry recording contains no drivable samples".into())}Ok(json!({"gameId":"lmu","version":l.meta.version,"recordingTime":l.meta.recording,"sessionType":l.meta.session,"driverName":l.meta.driver,"carName":l.meta.car,"carClass":l.meta.class,"trackName":l.meta.track,"estimatedPacketCount":(duration*RATE+1e-9).floor() as u64+1,"completedLapCount":lap_count.saturating_sub(1)}))}
pub(super) fn run(operation:&str, source:&Path, options:&Value, output:&Path, config:&Value)->Result<Value,String>{if options.get("captureStorage").and_then(Value::as_str)==Some("raw")||options.get("raw").and_then(Value::as_bool)==Some(true)||options.get("rawStorage").and_then(Value::as_bool)==Some(true){return Err("Raw capture storage is not supported for LMU DuckDB imports".into())}let dummy=json!({"input":{"path":source.to_string_lossy(),"sidecarPath":options.get("sidecarPath")},"jobId":"lmu-duckdb"});let private=copy_private(source,&dummy,output,config)?;let l=load(&private)?;if operation=="preview"{return preview(&private)}let packet_count=(l.duration*RATE+1e-9).floor() as usize+1;let epoch=epoch_ms(&l.meta.recording);let records=(0..packet_count).map(|i|{let t=l.start+i as f64/RATE;Ok(crate::formats::SourceRecord{offset:0,time_ms:Some((epoch as f64+(t-l.start)*1000.).max(0.) as u64),kind:crate::formats::RecordKind::Frame,payload:synth(&l,t,epoch)?})});super::capture::process_record_results(operation,records,"lmu-duckdb",options,output,config)}
